from ..models.article import ArticleCategory
KEYWORDS={ArticleCategory.EXPANSION:["plant","factory","capacity","expansion","facility"],ArticleCategory.ORDERS:["order","contract","agreement","supply deal"],ArticleCategory.FINANCIAL:["acquisition","merger","fundraising","capex","investment","debt"],ArticleCategory.PRODUCT:["launch","product","technology","patent","research"],ArticleCategory.MANAGEMENT:["appoint","resign","ceo","cfo","director","board"],ArticleCategory.LEGAL:["sebi","investigation","penalty","litigation","tax dispute","regulatory"],ArticleCategory.CREDIT:["credit rating","downgrade","upgrade","liquidity","repayment"],ArticleCategory.INDUSTRY:["industry","competitor","demand","policy","raw material"],ArticleCategory.GOVERNANCE:["auditor","related party","governance","fraud"]}
def classify_article(article):
    text=(article.headline+" "+article.content).lower(); article.categories=[cat for cat, words in KEYWORDS.items() if any(word in text for word in words)] or [ArticleCategory.INDUSTRY]; return article
